



UPDATE ELENCHIPROFESSIONALIBASE SET FLAG_REGIONALE=0;

UPDATE ANAGRAFE table1 SET table1.PROVINCIAELENCOPRO = (SELECT DISTINCT TABLE2.PROVINCIA FROM COMUNI table2 WHERE UPPER(table1.PROVINCIAELENCOPRO) = table2.SIGLAPROVINCIA) WHERE table1.PROVINCIAELENCOPRO IS NOT NULL AND EXISTS (SELECT 1 FROM COMUNI TABLE2 WHERE UPPER(table1.PROVINCIAELENCOPRO) = table2.SIGLAPROVINCIA);
